# FastAPI SSE endpoint streaming job progress from an in-memory job store
import asyncio, json
from fastapi import FastAPI, Request
from fastapi.responses import StreamingResponse

app = FastAPI()
JOBS: dict[str, dict] = {"abc": {"status": "running", "progress": 0}}

def sse(data: dict, event: str | None = None, id: str | None = None) -> str:
    msg = ""
    if id is not None:
        msg += f"id: {id}\n"
    if event:
        msg += f"event: {event}\n"
    msg += f"data: {json.dumps(data)}\n\n"        # blank line terminates the event
    return msg

@app.get("/jobs/{job_id}/events")
async def job_events(job_id: str, request: Request):
    async def stream():
        last = None
        ticks = 0
        while True:
            if await request.is_disconnected():   # client went away -> stop
                break
            job = JOBS.get(job_id)
            if job is None:
                yield sse({"error": "not found"}, event="error")
                break
            if job != last:
                yield sse(job, event="progress")
                last = dict(job)
            if job["status"] in ("done", "error", "cancelled"):
                break
            ticks += 1
            if ticks % 30 == 0:
                yield ": keep-alive\n\n"          # heartbeat comment
            await asyncio.sleep(0.5)              # non-blocking wait

    return StreamingResponse(
        stream(),
        media_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )
