// Browser client with EventSource
const es = new EventSource(`/jobs/${jobId}/events`);

es.addEventListener("progress", (e: MessageEvent) => {
  const job = JSON.parse(e.data) as { status: string; progress: number };
  progressBar.value = job.progress;
  if (["done", "error", "cancelled"].includes(job.status)) es.close(); // stop auto-reconnect
});

es.onerror = () => console.warn("SSE connection lost, browser will retry");
